    texto = re.sub(r"[A-Za-z]:(?:\\\\|\\|/)Users(?:\\\\|\\|/)[^\\/\"'\n]+", "~", texto)
    texto = re.sub(r"(?<![\w.+-])[\w.+-]+@[\w-]+(?:\.[\w-]+)*\.[A-Za-z]{2,}\b", _correo, texto)
    for termino in sorted(variantes_usuario(), key=len, reverse=True):
        texto = re.sub(re.escape(termino), "usuario", texto, flags=re.I)
    return texto
